/** Waits for the surface's open animation (its size and place are final after). */
async function finishAnimations(el: Element) {
  const animations = el.getAnimations({subtree: true});
  await Promise.all(animations.map((a): Promise<unknown> => a.finished.catch((): void => {})));
}

/** The focused element, looking inside shadow roots. */
function deepActive(): Element | null {
  let el = document.activeElement;
  while (el?.shadowRoot?.activeElement) el = el.shadowRoot.activeElement;
  return el;
}

async function setupAnchored0(opts: {edge?: 'top' | 'bottom' | 'end'} = {}) {
  const style = {
    bottom: 'bottom: 4px; left: 60px',
    top: 'top: 4px; left: 60px',
    end: 'top: 4px; right: 2px',
    none: 'top: 4px; left: 60px',
  }[opts.edge ?? 'none'];
  const root = await mount(html`
    <div style="position: fixed; ${style}">
      <md-gb-date-picker quick label="Date"></md-gb-date-picker>
    </div>
  `);
  const f = {
    root,
    get invoker() {
      return root.querySelector('md-gb-date-picker')!.shadowRoot!.querySelector<HTMLElement>('.date-picker-calendar-button')!;
    },
    get anchor() {
      return root.querySelector('md-gb-date-picker')!.shadowRoot!.querySelector<HTMLElement>('.date-picker-field')!;
    },
    get surface() {
      return root.querySelector('md-gb-date-picker')!.shadowRoot!.querySelector<HTMLElement>('.date-picker')!;
    },
  };
  return f;
}

describe('<md-gb-date-picker (docked)> anchored overlay contract (AnchoredOverlayController: popover, below, flip, light dismiss, focus return)', () => {
  afterEach(() => container?.remove());

  it('opens as a popover in the top layer, below its invoker, start-aligned', async () => {
    // spec: date-pickers-3556cc
    const f = await setupAnchored0();
    f.invoker.click();
    await settle();
    await finishAnimations(f.surface);
    expect(f.surface.matches(':popover-open')).toBeTrue();
    expect(f.surface.hasAttribute('popover')).toBeTrue();
    const a = f.anchor.getBoundingClientRect();
    const s = f.surface.getBoundingClientRect();
    expect(s.top).toBeGreaterThanOrEqual(a.bottom - 0.5);
    expect(Math.abs(s.top - a.bottom - 4)).toBeLessThan(1.5);
    expect(Math.abs(s.left - a.left)).toBeLessThan(1.5);
  });

  it('flips to the above when there is no room below', async () => {
    const f = await setupAnchored0({edge: 'bottom'});
    f.invoker.click();
    await settle();
    await finishAnimations(f.surface);
    expect(f.surface.matches(':popover-open')).toBeTrue();
    const a = f.anchor.getBoundingClientRect();
    const s = f.surface.getBoundingClientRect();
    expect(s.bottom).toBeLessThanOrEqual(a.top + 0.5);
    expect(Math.abs(a.top - s.bottom - 4)).toBeLessThan(1.5);
    expect(s.top).toBeGreaterThanOrEqual(-0.5);
    expect(s.bottom).toBeLessThanOrEqual(window.innerHeight + 0.5);
  });

  it('stays inside the window at its inline end', async () => {
    const f = await setupAnchored0({edge: 'end'});
    f.invoker.click();
    await settle();
    await finishAnimations(f.surface);
    expect(f.surface.matches(':popover-open')).toBeTrue();
    const s = f.surface.getBoundingClientRect();
    expect(s.left).toBeGreaterThanOrEqual(-0.5);
    expect(s.right).toBeLessThanOrEqual(document.documentElement.clientWidth + 0.5);
  });

  it('closes with Escape', async () => {
    const f = await setupAnchored0();
    f.invoker.click();
    await settle();
    await finishAnimations(f.surface);
    expect(f.surface.matches(':popover-open')).toBeTrue();
    await press('Escape');
    expect(f.surface.matches(':popover-open')).toBeFalse();
  });

  it('closes with a press outside', async () => {
    const f = await setupAnchored0();
    f.invoker.click();
    await settle();
    await finishAnimations(f.surface);
    expect(f.surface.matches(':popover-open')).toBeTrue();
    await sendMouse({type: 'click', position: [document.documentElement.clientWidth - 6, 6]});
    await settle();
    expect(f.surface.matches(':popover-open')).toBeFalse();
  });

  it('returns focus to the invoker when it was inside', async () => {
    const f = await setupAnchored0();
    f.invoker.focus();
  await press('Enter');
    await settle();
    expect(f.surface.matches(':popover-open')).toBeTrue();
    expect(deepActive()).not.toBe(f.invoker);
    await press('Escape');
    expect(f.surface.matches(':popover-open')).toBeFalse();
    expect(deepActive()).toBe(f.invoker);
  });
});

/** The live region of `politeness` in the shadow root of `el`. */
function annRegion(el: HTMLElement, politeness: 'polite' | 'assertive') {
  return el.shadowRoot!.querySelector<HTMLElement>(`[data-announcer="${politeness}"]`);
}

/** Waits (at most a second) until the live region holds `expected`, and returns its text. */
async function annText(el: HTMLElement, politeness: 'polite' | 'assertive', expected: string) {
  const text = () => annRegion(el, politeness)?.textContent?.trim() ?? '';
  // Checks once per frame (the shared until() helper, inlined).
  const end = performance.now() + 1000;
  while (text() !== expected && performance.now() < end) {
    await new Promise((resolve) => requestAnimationFrame(resolve));
  }
  return text();
}

describe('<md-gb-date-picker> announcer contract (AnnouncerController)', () => {
  afterEach(() => container?.remove());

  it('announces the new month politely when PageDown changes it', async () => {
    // spec: date-pickers-bebbe9, date-pickers-a7daa0
    const root = await mount(html`
      <button id="before">Before</button>
      <md-gb-date-picker inline quick locale="en-US" value="2025-08-17"></md-gb-date-picker>
    `);
    const el = root.querySelector<any>('md-gb-date-picker')!;
    const before = root.querySelector<HTMLElement>('#before')!;
    before.focus();
    await settle();
    const cell = el.shadowRoot.querySelector('[data-date="2025-08-17"]') as HTMLElement;
    cell.focus();
    await press('PageDown');
    const expected = 'September 2025';
    expect(expected).not.toBe('');
    expect(await annText(el, 'polite', expected)).toBe(expected);
    const region = annRegion(el, 'polite')!;
    expect(region.getAttribute('role')).toBe('status');
    expect(region.getAttribute('aria-live')).toBe('polite');
    expect(region.getAttribute('aria-atomic')).toBe('true');
  });

  it('announces the new month when Shift+PageUp changes the year', async () => {
    // spec: date-pickers-44900d
    const root = await mount(html`
      <button id="before">Before</button>
      <md-gb-date-picker inline quick locale="en-US" value="2025-08-17"></md-gb-date-picker>
    `);
    const el = root.querySelector<any>('md-gb-date-picker')!;
    const before = root.querySelector<HTMLElement>('#before')!;
    before.focus();
    await settle();
    const cell = el.shadowRoot.querySelector('[data-date="2025-08-17"]') as HTMLElement;
    cell.focus();
    await press('Shift+PageUp');
    const expected = 'August 2024';
    expect(expected).not.toBe('');
    expect(await annText(el, 'polite', expected)).toBe(expected);
    const region = annRegion(el, 'polite')!;
    expect(region.getAttribute('role')).toBe('status');
    expect(region.getAttribute('aria-live')).toBe('polite');
    expect(region.getAttribute('aria-atomic')).toBe('true');
  });

  it('removes its live regions when it disconnects', async () => {
    const root = await mount(html`<md-gb-date-picker inline quick locale="en-US" value="2025-08-17"></md-gb-date-picker>`);
    const el = root.querySelector<any>('md-gb-date-picker')!;
    const cell = el.shadowRoot.querySelector('[data-date="2025-08-17"]') as HTMLElement;
    cell.focus();
    await press('PageDown');
    await annText(el, 'polite', 'September 2025');
    expect(el.shadowRoot.querySelector('[data-announcer]')).not.toBeNull();
    el.remove();
    await settle();
    expect(el.shadowRoot.querySelector('[data-announcer]')).toBeNull();
  });
});

/** The form's entries, as submitted. */
function submittedEntries(form: HTMLFormElement) {
  return [...new FormData(form).entries()].map(([k, v]) => [k, String(v)]);
}

async function setupFormPicker(attrs: Record<string, string> = {}) {
  const root = await mount(html`
    <form>
      <fieldset>
        <md-gb-date-picker name="when" quick label="Date"></md-gb-date-picker>
      </fieldset>
    </form>
  `);
  const el = root.querySelector<any>('md-gb-date-picker')!;
  for (const [name, value] of Object.entries(attrs)) el.setAttribute(name, value);
  await settle();
  return {
    el,
    form: root.querySelector('form')!,
    fieldset: root.querySelector('fieldset')!,
  };
}

/** Picks a different value with real keys. */
async function pickFormPicker(f: {el: any}) {
  await f.el.show();
  await settle();
  await press('ArrowRight');
  await press('Enter');
  await settle();
}

describe('<md-gb-date-picker> form contract (shared form layer)', () => {
  afterEach(() => container?.remove());

  it('submits the picked value under its name, and nothing before', async () => {
    const f = await setupFormPicker();
    expect(f.el.value).toBe('');
    expect(submittedEntries(f.form)).toEqual([]);
    await pickFormPicker(f);
    expect(f.el.value).not.toBe('');
    expect(submittedEntries(f.form)).toEqual([['when', f.el.value]]);
  });

  it('starts on the value attribute and resets to it', async () => {
    const f = await setupFormPicker({value: '2025-08-17'});
    expect(f.el.value).toBe('2025-08-17');
    expect(submittedEntries(f.form)).toEqual([['when', '2025-08-17']]);
    await pickFormPicker(f);
    expect(f.el.value).not.toBe('2025-08-17');
    f.form.reset();
    await settle();
    expect(f.el.value).toBe('2025-08-17');
    expect(submittedEntries(f.form)).toEqual([['when', '2025-08-17']]);
  });

  it('ignores the value attribute after the person picked, until reset', async () => {
    const f = await setupFormPicker({value: '2025-08-17'});
    await pickFormPicker(f);
    const picked = f.el.value;
    f.el.setAttribute('value', '2025-09-02');
    await settle();
    expect(f.el.value).toBe(picked);
    f.form.reset();
    await settle();
    f.el.setAttribute('value', '2025-09-02');
    await settle();
    expect(f.el.value).toBe('2025-09-02');
  });

  it('restores the saved value', async () => {
    const f = await setupFormPicker();
    f.el.formStateRestoreCallback('2025-08-17', 'restore');
    await settle();
    expect(f.el.value).toBe('2025-08-17');
    expect(submittedEntries(f.form)).toEqual([['when', '2025-08-17']]);
  });

  it('is invalid while required and empty, valid once picked', async () => {
    const f = await setupFormPicker({required: ''});
    expect(f.el.validity.valueMissing).toBeTrue();
    expect(f.form.checkValidity()).toBeFalse();
    await pickFormPicker(f);
    expect(f.el.validity.valid).toBeTrue();
    expect(f.form.checkValidity()).toBeTrue();
  });

  it('setCustomValidity() invalidates until cleared', async () => {
    const f = await setupFormPicker();
    f.el.setCustomValidity('Not available');
    expect(f.el.validity.customError).toBeTrue();
    expect(f.el.validationMessage).toBe('Not available');
    expect(f.form.checkValidity()).toBeFalse();
    f.el.setCustomValidity('');
    expect(f.el.validity.valid).toBeTrue();
  });

  it('blocks a submit while invalid and lets it through once valid', async () => {
    const f = await setupFormPicker({required: ''});
    let submitted = 0;
    f.form.addEventListener('submit', (e) => {
      e.preventDefault();
      submitted++;
    });
    f.form.requestSubmit();
    expect(submitted).toBe(0);
    await pickFormPicker(f);
    f.form.requestSubmit();
    expect(submitted).toBe(1);
  });

  it('reportValidity() fires invalid and shows the error until valid', async () => {
    const f = await setupFormPicker({required: ''});
    const shown = () => (f.el.shadowRoot!.querySelector('md-gb-text-field') as any).error as boolean;
    let invalid = 0;
    f.el.addEventListener('invalid', () => invalid++);
    expect(shown()).toBeFalse();
    expect(f.el.reportValidity()).toBeFalse();
    await settle();
    expect(invalid).toBe(1);
    expect(shown()).toBeTrue();
    await pickFormPicker(f);
    expect(shown()).toBeFalse();
  });

  it('follows a disabled fieldset, is left out of the form and recovers', async () => {
    // spec: date-pickers-f856b3
    const f = await setupFormPicker({value: '2025-08-17'});
    expect(f.el.disabled).toBeFalse();
    f.fieldset.disabled = true;
    await settle();
    expect(f.el.disabled).toBeTrue();
    expect((f.el.shadowRoot!.querySelector('.date-picker-calendar-button') as HTMLButtonElement).disabled).toBeTrue();
    expect(submittedEntries(f.form)).toEqual([]);
    f.fieldset.disabled = false;
    await settle();
    expect(f.el.disabled).toBeFalse();
    expect((f.el.shadowRoot!.querySelector('.date-picker-calendar-button') as HTMLButtonElement).disabled).toBeFalse();
    expect(submittedEntries(f.form)).toEqual([['when', '2025-08-17']]);
  });

  it('is not validated while disabled', async () => {
    // spec: date-pickers-f856b3
    const f = await setupFormPicker({required: ''});
    f.fieldset.disabled = true;
    await settle();
    expect(f.el.willValidate).toBeFalse();
    expect(f.form.checkValidity()).toBeTrue();
  });
});

import {resetEscapeTracking} from '../shared/predictive-back.js';

/** What the lifecycle surfaces share: `show()`, `close()`, `open` and events. */
interface ModalLifecycleElement extends HTMLElement {
  open: boolean;
  show(): Promise<void>;
  close(...args: string[]): Promise<void>;
}

/** Records open / opened / close / closed, with `:reason` for close events. */
function modalRecord(el: HTMLElement) {
  const log: string[] = [];
  for (const type of ['open', 'opened', 'close', 'closed']) {
    el.addEventListener(type, (event) => {
      const reason = (event as CustomEvent).detail?.reason;
      log.push(reason ? `${type}:${reason}` : type);
    });
  }
  return log;
}

function modalOnce(el: HTMLElement, type: string) {
  return new Promise<void>((resolve) =>
    el.addEventListener(type, () => resolve(), {once: true}),
  );
}

/**
 * A close request counts as Escape for a second after an Escape press (the
 * browser reports Escape and the back gesture alike). Forgets the recorded
 * presses, so the next close request is a back request.
 */
function modalForgetEscape() {
  resetEscapeTracking();
}

/** Whether the page scroll is locked (CSS overflow of the root element). */
function modalPageLocked() {
  return getComputedStyle(document.documentElement).overflow === 'hidden';
}

async function setupModalDatePicker() {
  const root = await mount(html`<button id="before">Before</button><md-gb-date-picker variant="modal" quick label="Date"></md-gb-date-picker>`);
  const el = root.querySelector<ModalLifecycleElement>('md-gb-date-picker')!;
  await settle();
  return {el, before: root.querySelector<HTMLElement>('#before')!};
}

async function openModalDatePicker(el: ModalLifecycleElement) {
  await el.show();
  await settle();
}

function isOpenModalDatePicker(el: ModalLifecycleElement) {
  return el.open;
}

describe('<md-gb-date-picker> modal surface contract (modal date picker; ModalSurfaceController)', () => {
  afterEach(() => container?.remove());

  it('fires open and opened when it opens, and open can be canceled', async () => {
    const {el} = await setupModalDatePicker();
    const log = modalRecord(el);
    await el.show();
    expect(log).toEqual(['open', 'opened']);
    expect(el.open).toBeTrue();
    await el.close();
    const canceled = await setupModalDatePicker();
    canceled.el.addEventListener('open', (event) => event.preventDefault());
    await canceled.el.show();
    expect(canceled.el.open).toBeFalse();
  });

  it('fires a cancelable close and closed with detail.reason, and stays open when close is canceled', async () => {
    const {el} = await setupModalDatePicker();
    await el.show();
    const log = modalRecord(el);
    await el.close('custom');
    expect(log).toEqual(['close:custom', 'closed:custom']);
    expect(el.open).toBeFalse();
    await el.show();
    el.addEventListener('close', (event) => event.preventDefault(), {once: true});
    await el.close();
    expect(el.open).toBeTrue();
  });

  it('closes on Escape with the escape reason', async () => {
    const {el} = await setupModalDatePicker();
    await openModalDatePicker(el);
    const log = modalRecord(el);
    const closed = modalOnce(el, 'closed');
    await press('Escape');
    await closed;
    expect(isOpenModalDatePicker(el)).toBeFalse();
    expect(log).toEqual(['close:escape', 'closed:escape']);
  });

  it('closes on a scrim click with the scrim reason', async () => {
    // spec: date-pickers-37dbeb, date-pickers-135584
    const {el} = await setupModalDatePicker();
    await openModalDatePicker(el);
    const log = modalRecord(el);
    const closed = modalOnce(el, 'closed');
    el.shadowRoot!.querySelector('dialog')!.click();
    await closed;
    expect(isOpenModalDatePicker(el)).toBeFalse();
    expect(log).toEqual(['close:scrim', 'closed:scrim']);
  });

  it('closes on a back request with the back reason', async () => {
    const {el} = await setupModalDatePicker();
    await openModalDatePicker(el);
    const dialog = el.shadowRoot!.querySelector('dialog')!;
    if (typeof dialog.requestClose !== 'function') {
      pending('HTMLDialogElement.requestClose() is not supported');
    }
    const log = modalRecord(el);
    const closed = modalOnce(el, 'closed');
    await modalForgetEscape();
    dialog.requestClose();
    await closed;
    expect(isOpenModalDatePicker(el)).toBeFalse();
    expect(log).toEqual(['close:back', 'closed:back']);
  });

  it('moves focus into the surface when it opens and restores it when it closes', async () => {
    // spec: date-pickers-795bcb
    const {el, before} = await setupModalDatePicker();
    before.focus();
    await openModalDatePicker(el);
    expect(el.matches(':focus-within')).withContext('focus is inside').toBeTrue();
    const closed = modalOnce(el, 'closed');
    await press('Escape');
    await closed;
    expect(document.activeElement).toBe(before);
  });

  it('keeps Tab and Shift+Tab inside the surface', async () => {
    // spec: date-pickers-795bcb
    const {el} = await setupModalDatePicker();
    await openModalDatePicker(el);
    for (let i = 0; i < 6; i++) {
      await press('Tab');
      expect(el.matches(':focus-within')).withContext(`after Tab ${i + 1}`).toBeTrue();
    }
    for (let i = 0; i < 6; i++) {
      await press('Shift+Tab');
      expect(el.matches(':focus-within')).withContext(`after Shift+Tab ${i + 1}`).toBeTrue();
    }
  });

  it('locks page scrolling while it is open, and releases the lock when it closes', async () => {
    const {el} = await setupModalDatePicker();
    expect(modalPageLocked()).toBeFalse();
    await openModalDatePicker(el);
    expect(modalPageLocked()).toBeTrue();
    const closed = modalOnce(el, 'closed');
    await press('Escape');
    await closed;
    expect(modalPageLocked()).toBeFalse();
  });
});
